INSERT INTO `email_templates` (`id`, `jenis_monitoring`, `nama_template`, `subject`, `body`, `kategori`, `created_at`, `updated_at`) VALUES
(1, 'W001-WIP', 'W001-WIP1', 'WIP {{tanggal_kirim}} - {{company_name}}', '<div style=\"line-height: 1;\"><span style=\"color: rgb(0, 0, 0); font-family: Bahnschrift; font-size: 12px;\">\r\n\r\n</span><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><span style=\"font-family: &quot;Segoe UI&quot;;\">Dear Team,</span></p><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><span style=\"font-family: &quot;Bahnschrift&quot;;\"><br></span></p><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><span style=\"font-family: &quot;Segoe UI&quot;;\">Izin mengingatkan&nbsp;</span><span style=\"font-family: &quot;Segoe UI&quot;;\">agar dapat update RMA Return / no. AWB return part dan tanggal part return di ISD utk case2 terlampir.</span></p><span style=\"color: rgb(0, 0, 0); font-family: &quot;Segoe UI&quot;; font-size: 12px;\">\r\n\r\n</span><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><strong><span style=\"font-family: &quot;Bahnschrift&quot;;\"><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\n</span><span style=\"font-size: 12px; font-family: &quot;Segoe UI&quot;;\">Untuk part yang belum dikembalikan bisa segera dikembalikan dan segera update no AWB return di ISD,\r\n</span></span></strong></p><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><strong><span style=\"font-family: &quot;Segoe UI&quot;; font-size: 12px;\">dan untuk part yang sudah dikembalikan bisa di update no AWB Returnnya di ISD.</span></strong></p><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><strong><span style=\"font-family: &quot;Bahnschrift&quot;;\"><br></span></strong></p><p style=\"margin-top: 0px; margin-bottom: 0px; line-height: 1;\"><font face=\"Bahnschrift\" color=\"#ff0000\"><span style=\"font-size: 12px;\"><b style=\"\"><span style=\"font-family: &quot;Segoe UI&quot;;\">Mohon perhatiannya untuk proses pengembalian spare part sudah tidak menggunakan macro tetapi menggunakan link RCT. </span></b></span></font></p><p style=\"margin-top: 0px; margin-bottom: 0px; line-height: 1;\"><font face=\"Bahnschrift\" color=\"#ff0000\"><span style=\"font-size: 12px;\"><b style=\"\"><span style=\"font-family: &quot;Segoe UI&quot;;\">Untuk tutorial bisa cek link https://centerhub.taplink.site nomer 010.</span><br></b></span></font><b style=\"font-size: 12px; color: rgb(255, 0, 0); font-family: Bahnschrift;\"><span style=\"font-family: &quot;Segoe UI&quot;;\">Mohon perhatiannya terhadap spare part&nbsp; DNRB (Do Not Return Bad), pastikan agar spare part ini tidak dikembalikan ke logistik.</span></b></p><div style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; line-height: 1;\"><br></div><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><strong><span style=\"font-family: &quot;Segoe UI&quot;; font-size: 12px;\">\r\n</span></strong><span style=\"font-family: &quot;Segoe UI&quot;; font-size: 12px;\">\r\n</span></p><span style=\"color: rgb(0, 0, 0); font-family: &quot;Segoe UI&quot;; font-size: 12px;\">\r\n</span><p style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px; margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><strong><span style=\"font-family: &quot;Bahnschrift&quot;;\"><span style=\"font-size: 12px; font-family: &quot;Segoe UI&quot;;\">\r\nNote:\r\nPastikan juga bahwa softcopy bukti / fisik resinya tersimpan dengan baik sehingga bisa digunakan jika diperlukan nantinya.\r\nDan jangan lupa untuk foto fisik part sebelum melakukan pengembalian spare part.</span><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\n</span></span></strong><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\n</span></p><span style=\"color: rgb(0, 0, 0); font-family: &quot;Segoe UI&quot;; font-size: 12px;\">\r\n\r\n</span><br><span style=\"color: rgb(0, 0, 0); font-family: &quot;Segoe UI&quot;; font-size: 12px;\">\r\n\r\n[[TABEL_CASE]]</span></div><div style=\"font-family: Arial, sans-serif; font-size: 12px; color: rgb(0, 0, 0); line-height: 1.2;\"><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\n\r\n</span></div><div style=\"font-family: Arial, sans-serif; font-size: 12px; color: rgb(0, 0, 0); line-height: 1.2;\"><span style=\"font-family: &quot;Bahnschrift&quot;;\"><br></span><p style=\"margin-top: 0px; margin-bottom: 0px; line-height: 1.2;\"><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\nRegards,</span><br><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\nVira</span><br><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\nMaster Hub Center</span><br><span style=\"font-family: &quot;Segoe UI&quot;;\">\r\n</span><img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" border=\"0\" alt=\"Logo Master Hub Center\" style=\"display:block;\"><span style=\"font-family: &quot;Bahnschrift&quot;;\">\r\n</span></p><span style=\"font-family: &quot;Bahnschrift&quot;;\">\r\n\r\n</span></div>', 'apo2', '2026-06-05 22:23:00', '2026-10-14 08:25:30'),
(3, 'W003-TAT5D (Pending case 5 days)', 'W003-TAT5D1', 'Pending Case ISD 5days {{tanggal_kirim}} - {{company_name}}', '<div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">Dear Partner,</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">Menindaklanjuti perbaikan TAT yang lalu, maka untuk maintain TAT agar tetap baik maka kita perlu cek progress sampai dengan finish repair/CLOSE CASE sbb:</p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">1. Prioritas Pertama : Fokus kepada case-case yang baru masuk dan usahakan Meet TAT &lt; 5 hari. Semakin banyak case yang meet yang bisa di close semakin bagus.\r\n<br>\r\n[[TABEL_PENDING_BELOW_5]]\r\n</p>\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">2. Prioritas Kedua adalah case-case yang sudah miss TAT nya (diatas 5 hari)\r\n<br>\r\n[[TABEL_PENDING_ABOVE_5]]\r\n</p>\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">Semoga dengan cara ini, kita dapat meningkatkan performa TAT khususnya di Bench masing-masing.</p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\n</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p><p style=\"margin-top: 0px; margin-bottom: 0px;\">Regards,<br>\r\nVira<br>\r\nMaster Hub Center<br>\r\n<img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" border=\"0\" alt=\"Logo Master Hub Center\" style=\"display:block;\">\r\n</p>\r\n\r\n</div>', 'apo2', '2026-06-06 08:28:40', '2026-10-13 03:58:00'),
(4, 'W001-WIP', 'W001-WIP2', 'WIP {{tanggal_kirim}} - {{company_name}}', '<div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">Dear Team,</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nMohon update RMA Return / no. AWB return part dan tanggal part return di ISD utk case2 terlampir yaa.\r\n</p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\"><strong>\r\nUntuk part yang belum dikembalikan bisa segera dikembalikan dan segera update no AWB return di ISD,\r\n</strong></p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><strong>Dan untuk part yang sudah dikembalikan bisa di update no AWB Returnnya di ISD.\r\n</strong>\r\n</p>\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nNote:<br><strong>\r\nPastikan juga bahwa softcopy bukti / fisik resinya tersimpan dengan baik sehingga bisa digunakan jika diperlukan nantinya.\r\nDan jangan lupa untuk foto fisik part sebelum melakukan pengembalian spare part.\r\n</strong>\r\n</p>\r\n\r\n[[TABEL_CASE]]</div><div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n\r\n<br>\r\n\r\n<p style=\"font-size: 12px; margin-top: 0px; margin-bottom: 0px;\">\r\n<a href=\"https://drive.google.com/file/d/1SZTzNDdnFFc-7k5tt_jI3JshYH5Xu92T/view?usp=sharing\">\r\nhttps://drive.google.com/file/d/1SZTzNDdnFFc-7k5tt_jI3JshYH5Xu92T/view?usp=sharing\r\n</a>\r\n<br>\r\n<br>\r\nDan sudah kami lampirkan juga tekait diagram alur WIP dan link video tutorial update no AWB di ISD, apabila ada yang ingin ditanyakan terkait alur WIP  bisa langsung menghubungi kami.\r\n</p>\r\n\r\n</div><div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\"><br></div><div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">Regards,<br>\r\nVira<br>\r\nMaster Hub Center<br>\r\n<img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" border=\"0\" alt=\"Logo Master Hub Center\" style=\"display: block;\"><br>\r\n\r\n</div>', 'apo2', '2026-06-07 05:54:55', '2026-10-13 03:55:09'),
(5, 'W002-TAT14D (Pending case 14 days)', 'W002-TAT14D1', 'Pending Case 14 Days - {{tanggal_kirim}} {{company_name}}', '<div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">Dear Partner,</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nMohon segera update terkait case berikut ini, terutama untuk case yang agingnya sudah lebih dari 14 hari.\r\n</p>\r\n\r\n[[TABEL_CASE]]</div><div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n\r\n<br>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nSemoga dengan cara ini, kita dapat meningkatkan performa TAT khususnya di Bench masing-masing.\r\n</p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nRegards,<br>\r\n<b>Vira</b><br>\r\nMaster Hub Center\r\n</p>\r\n\r\n<img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" alt=\"Logo Master Hub Center\" style=\"display:block;\">\r\n\r\n<br>\r\n\r\n</div>', 'apo2', '2026-06-27 04:06:49', '2026-10-13 03:57:40'),
(6, 'W004-KCI', 'W004-KCI1', 'KCI - {{tanggal_kirim}} {{company_name}}', '<div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">Dear Team,</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nBerikut terlampir case-case yang masih pending.<br>\r\n1. Untuk case yang masih open, mohon informasikan update progressnya kepada user.<br>\r\n2. Untuk case yang sudah finish repair, segera hubungi user untuk dapat mengambil unit agar case bisa segera di close repair.</p>[[TABEL_CASE]]\r\n\r\n</div><div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\"><br></div><div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\"><p style=\"margin-top: 0px; margin-bottom: 0px;\"><b style=\"background-color: rgb(255, 255, 0);\">* Untuk setiap case wajib melakukan update informasi ke user, baik ada maupun tidak ada perkembangan dari case.&nbsp;</b></p><br>\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nRegards,<br>\r\nVira<br>\r\nMaster Hub Center<br>\r\n<img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" border=\"0\" alt=\"Logo Master Hub Center\" style=\"display:block;\">\r\n</p>\r\n</div>', 'apo2', '2026-07-03 07:36:02', '2026-10-13 03:58:11'),
(7, 'W005-FR (Finish Repair)', 'W005-FR1', 'Finish Repair - {{tanggal_kirim}} {{company_name}}', '<div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">Dear Team,</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p>\r\n\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nBerikut adalah case-case yang sudah finish repair dan perlu diupdate statusnya ke close repair :<br>\r\n- Untuk unit yang sudah diambil oleh user bisa segera update status menjadi close repair.<br>\r\n- Untuk unit yang belum diambil oleh user, mohon konfirmasi jadwal pengambilan kepada user dan update hasil konfirmasi tersebut di lognote ISD.\r\n</p>\r\n\r\n[[TABEL_CASE]]</div><div style=\"font-family: Arial, sans-serif; font-size:12px; color:#000; line-height:1.5;\">\r\n\r\n<br>\r\n<p style=\"margin-top: 0px; margin-bottom: 0px;\">\r\nRegards,<br>\r\nVira<br>\r\nMaster Hub Center<br>\r\n<img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" border=\"0\" alt=\"Logo Master Hub Center\" style=\"display:block;\">\r\n</p>\r\n</div>', 'apo2', '2026-07-03 07:37:12', '2026-10-13 03:57:28'),
(8, 'W005-FR (Finish Repair)', 'W005-FR2', 'Finish Repair - {{tanggal_kirim}} {{company_name}}', '<div style=\"font-family: Arial, sans-serif; font-size: 12px; color: rgb(0, 0, 0); line-height: 1.5;\"><p style=\"margin-top: 0px; margin-bottom: 0px;\">Dear Team,</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p><p style=\"margin-top: 0px; margin-bottom: 0px;\">Berikut adalah case-case yang sudah finish repair dan perlu diupdate statusnya ke close repair :<br>- Untuk unit yang sudah diambil oleh user bisa segera update status menjadi close repair.<br>- Untuk unit yang belum diambil oleh user, mohon konfirmasi jadwal pengambilan kepada user dan update hasil konfirmasi tersebut di lognote.</p>[[TABEL_CASE]]</div><div style=\"font-family: Arial, sans-serif; font-size: 12px; color: rgb(0, 0, 0); line-height: 1.5;\"><br></div><div style=\"font-family: Arial, sans-serif; font-size: 12px; color: rgb(0, 0, 0); line-height: 1.5;\">Note: mengingatkan agar dapat close repair case2 yg sudah diambil oleh cust pada sistem ISD agar dapat dihitung pada perhitungan labor bulan ini.<div style=\"line-height: 1.5;\"><br></div><p style=\"margin-top: 0px; margin-bottom: 0px;\">Regards,<br>Vira<br>Master Hub Center<br><img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" border=\"0\" alt=\"Logo Master Hub Center\" style=\"display: block;\"></p></div>', 'apo2', '2026-07-21 08:36:10', '2026-10-13 03:56:55'),
(9, 'W001-WIP', 'W001-WIP3', 'WIP {{tanggal_kirim}} - {{company_name}}', '<p style=\"margin-top: 0px; margin-bottom: 0px;\"><span style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px;\">Dear Team,</span></p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><span style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px;\"><br></span></p><div style=\"line-height: 1.5;\"><p style=\"margin-top: 0px; margin-bottom: 0px;\"><font color=\"#000000\" face=\"Arial, sans-serif\"><span style=\"font-size: 12px;\">Izin mengingatkan bahwa dengan mulai bertambahnya pending part yg belum di-return ke Warehouse, berikut list spare part agar dapat segera return partnya, terutama utk case yg sudah close/finish dan aging peminjaman part nya sudah lama.<br></span></font><span style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px;\">Mohon update RMA Return / no. AWB return part dan tanggal part return di ISD utk case2 terlampir ya.<br></span><span style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px;\"><br>Note: Pastikan juga bahwa softcopy bukti / fisik resinya tersimpan dengan baik sehingga bisa digunakan jika diperlukan nantinya. Dan jangan lupa untuk foto fisik part sebelum melakukan pengembalian spare part.<br><br></span></p><font color=\"#000000\" face=\"Arial, sans-serif\"><span style=\"font-size: 12px;\">[[TABEL_CASE]]</span></font></div><div style=\"font-family: Arial, sans-serif; font-size: 12px; color: rgb(0, 0, 0); line-height: 1.5;\"><br><p style=\"margin-top: 0px; margin-bottom: 0px;\"><a href=\"https://drive.google.com/file/d/1SZTzNDdnFFc-7k5tt_jI3JshYH5Xu92T/view?usp=sharing\">https://drive.google.com/file/d/1SZTzNDdnFFc-7k5tt_jI3JshYH5Xu92T/view?usp=sharing</a><br><br>Dan sudah kami lampirkan juga tekait diagram alur WIP dan link video tutorial update no AWB di ISD, apabila ada yang ingin ditanyakan terkait alur WIP bisa langsung menghubungi kami.</p><p style=\"margin-top: 0px; margin-bottom: 0px;\"><br></p>Regards,<br>Vira<br>Master Hub Center<br><img src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjs9YUvQxCD2GsPvHN-IDTPOS3MzmqsvhspEUlJOL7Gzu5hHyQceyN8tPzsPTsupiQVO-udzfyLGgcbw-7jLxNUHT9BnUyVcM9ue0EP0wIS6ZJi2_7YlSm8rjDqJeXohl7a7UPbzOTsvKDSKaJuRV3CunRFq0pHze510iUqYl2rQijkYzD5b3DFX_qWO3eQ/s1600/apo2.png\" width=\"85\" border=\"0\" alt=\"Logo Master Hub Center\" style=\"display: block;\"></div><div><br></div>', 'apo2', '2026-07-21 08:49:17', '2026-10-13 03:54:47'),
(12, 'M002-RI (Reminder Invoice)', 'M002-RI1', '[HP Central Hub] Reminder Invoice dan Kelengkapan Labor Periode Juni 2026 - {{company_name}}', '<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 12pt; color: black;\">Dear Our Valued\r\nPartner,</span><span style=\"font-size: 12pt;\"><o:p><br></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 12pt;\"><o:p><br></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 12pt; color: black;\">Berikut kami\r\nsampaikan beberapa hal sbb:</span><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><u><span style=\"font-size: 12pt; color: black;\">1. Pending Invoice:</span></u></b><b><span style=\"font-size: 12pt; color: black;\"> kami\r\ninformasikan untuk beberapa dokumen pendukung yang belum lengkap adalah :</span></b><span style=\"font-size: 12pt; color: black;\"><br>\r\n<!--[if !supportLineBreakNewLine]--><br>\r\n<!--[endif]--></span><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"color: rgb(0, 0, 0); font-family: Arial, sans-serif; font-size: 12px;\">[[TABEL_CASE]]</span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 12pt; color: black;\">Mohon untuk segera\r\nmengirimkan softcopy invoice dan kelengkapan dokumen (scan SRF + ERF) via email\r\n&amp; mengirimkan hardcopy <b><span style=\"background:yellow\">segera</span>.</b></span><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><span style=\"font-size: 12pt; color: black;\">**Disarankan tetap\r\nlakukan pengiriman setiap bulan untuk menghindari dokumen hilang / terselip.</span></b><span style=\"font-size: 12pt;\"><o:p><br></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 12pt;\"><o:p><br></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 12pt; color: black;\">&nbsp;<b><u>2.\r\nPemberitahuan Batas Terima Invoice</u></b></span><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-size: 12pt; color: black;\">Sehubungan dengan\r\nperjanjian Agreement terbaru Fy26, berikut kami informasikan beberapa hal\r\nterkait tagihan case labor sebagai berikut :</span><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><span style=\"font-size: 12pt; color: black;\">- Batas waktu\r\npenerimaan softcopy &amp; hardcopy dokumen untuk seluruh case periode Juni 2026\r\nyang belum ditagih adalah tanggal <span style=\"background:yellow\">31\r\nDesember 2026</span> dan (batas waktu terakhir).</span></b><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><span style=\"font-size: 12pt; color: black;\">- <span style=\"background:yellow\">Jika ada invoice dan kelengkapan data (SRF &amp; ERF)\r\nyang dikirimkan melebihi dari tanggal batas waktu terakhir tersebut, maka\r\ninvoice tersebut tidak bisa kami proses.</span></span></b><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><span style=\"font-size: 12pt; color: black; background: yellow;\">-\r\nJika ada tagihan atau invoice yang melebihi batas waktu terakhir maka invoice\r\ntsb tidak dapat dicairkan lagi</span></b><b><span style=\"font-size: 12pt; color: black;\"> (<span style=\"background:yellow\">HANGUS</span>).</span></b><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><i><span style=\"font-size: 12pt; color: black;\"><br></span></i></b></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><i><span style=\"font-size: 12pt; color: black;\">Note :</span></i></b><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b><i><span style=\"font-size: 12pt; color: black;\">- Payment term /\r\njatuh tempo pembayaran invoice labor adalah 95 hari setelah <span style=\"background:yellow\">invoice dan kelengkapan dokumen (scan SRF+ERF) kami\r\nterima via email (soft copy).</span></span></i></b><span style=\"font-size: 12pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: 1; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; backgroun